import React, { useState, useRef, useMemo, useCallback, useEffect } from 'react';
import { useReactToPrint } from 'react-to-print';
import html2canvas from 'html2canvas';
import jsPDF from 'jspdf';
import IndividualReport from '../Components/IndividualReport';
import ClassMarklist from '../Components/ClassMarklist';
import ExamNavigation from '../Components/ExamNavigation';
import { fetchResults } from '../api/results';
import '../Components/examModuleStyles.css';

const Reports = () => {
  const [allStudents, setAllStudents] = useState([]);
  const [selectedClass, setSelectedClass] = useState('All Classes');
  const [selectedExamType, setSelectedExamType] = useState('All Exams');
  const [selectedTerm, setSelectedTerm] = useState('All Terms');
  const [marklistClass, setMarklistClass] = useState('All Classes');
  const [loading, setLoading] = useState(true);
  const [selectedStudentId, setSelectedStudentId] = useState("");
  const [studentSearchTerm, setStudentSearchTerm] = useState("");
  // Set print orientation based on class (landscape for Grade 5-9)
  const [printOrientation, setPrintOrientation] = useState('portrait');

  // Automatically set orientation based on selected class for marklists
  useEffect(() => {
    if (marklistClass && marklistClass !== 'All Classes') {
      const gradesRequiringLandscape = ['Grade 5', 'Grade 6', 'Grade 7', 'Grade 8', 'Grade 9'];
      if (gradesRequiringLandscape.includes(marklistClass)) {
        setPrintOrientation('landscape');
      } else {
        setPrintOrientation('portrait');
      }
    }
  }, [marklistClass]);
  const [downloadingClass, setDownloadingClass] = useState(false);
  const [downloadingIndividual, setDownloadingIndividual] = useState(false);

  const individualRef = useRef();
  const classRef = useRef();

  // Fetch all results on component mount
  useEffect(() => {
    const loadResults = async () => {
      try {
        setLoading(true);
        const results = await fetchResults();
        // Ensure results is always an array
        setAllStudents(Array.isArray(results) ? results : []);
      } catch (error) {
        console.error('Error fetching results:', error);
        setAllStudents([]); // Set empty array on error
      } finally {
        setLoading(false);
      }
    };
    loadResults();
  }, []);

  // Filter students based on selected class and exam type for individual reports
  const filteredStudents = useMemo(() => {
    // Ensure allStudents is an array before filtering
    let filtered = Array.isArray(allStudents) ? allStudents : [];

    if (selectedClass !== 'All Classes') {
      filtered = filtered.filter(student => student.class === selectedClass);
    }

    if (selectedExamType !== 'All Exams') {
      filtered = filtered.filter(student => student.examType === selectedExamType);
    }

    if (selectedTerm !== 'All Terms') {
      filtered = filtered.filter(student => student.term === selectedTerm);
    }

    // Separate students by exam status for proper ranking
    const studentsWhoSat = filtered.filter(s => 
      (s.examStatus === 'sat' || !s.examStatus) && // Include sat and backward compatibility
      typeof s.mean === 'number' && !isNaN(s.mean)
    );
    const absentStudents = filtered.filter(s => s.examStatus === 'absent');
    const incompleteStudents = filtered.filter(s => s.examStatus === 'incomplete');
    const studentsWithoutMean = filtered.filter(s => 
      !(typeof s.mean === 'number' && !isNaN(s.mean)) && 
      (!s.examStatus || s.examStatus === 'sat') // Only sat students without mean
    );

    // Sort students who sat by mean score in descending order and add proper academic ranking
    studentsWhoSat.sort((a, b) => b.mean - a.mean);

    // Assign positions using proper academic ranking with tie handling (only for students who sat)
    // Robust approach that handles floating-point precision issues
    let position = 1;
    for (let i = 0; i < studentsWhoSat.length; i++) {
      if (i === 0) {
        // First student always gets position 1
        position = 1;
      } else {
        // Compare both mean and total for robust tie detection
        const currentMean = Math.round(studentsWhoSat[i].mean * 100) / 100;
        const previousMean = Math.round(studentsWhoSat[i-1].mean * 100) / 100;
        const currentTotal = studentsWhoSat[i].total || 0;
        const previousTotal = studentsWhoSat[i-1].total || 0;

        // If either mean OR total is different, it's not a tie
        if (currentMean !== previousMean || currentTotal !== previousTotal) {
