const express = require('express');
const router = express.Router();
const Result = require('../models/Result');

// Validation helper for academic year
const validateAcademicYear = (academicYear, useDefault = true) => {
  // If no academic year provided, use default (for backward compatibility)
  if (!academicYear) {
    if (useDefault) {
      return { isValid: true, academicYear: '2025' }; // Default to current data year
    } else {
      return { isValid: false, message: 'Academic year is required' };
    }
  }

  const yearStr = academicYear.toString().trim();
  const currentYear = new Date().getFullYear();
  const year = parseInt(yearStr);

  if (!/^\d{4}$/.test(yearStr) || year < 2020 || year > currentYear + 2) {
    return { 
      isValid: false, 
      message: `Academic year must be a 4-digit year between 2020 and ${currentYear + 2}` 
    };
  }

  return { isValid: true, academicYear: yearStr };
};

// Validation helper for exam status
const validateExamStatus = (examStatus) => {
  const validStatuses = ['sat', 'absent', 'incomplete'];

  if (!examStatus) {
    return { isValid: true, examStatus: 'sat' }; // Default to 'sat' for backward compatibility
  }

  if (!validStatuses.includes(examStatus)) {
    return {
      isValid: false,
      message: `Exam status must be one of: ${validStatuses.join(', ')}`
    };
  }

  return { isValid: true, examStatus };
};

// Helper to clear scores for absent students
const processExamStatusData = (data) => {
  if (data.examStatus === 'absent') {
    // Clear all subject scores for absent students
    const subjectFields = ['maths', 'english', 'kiswahili', 'language', 'reading', 
                           'environmental', 'integrated', 'creative', 'cre', 'kusoma', 
                           'social', 'pretech', 'agriculture'];

    subjectFields.forEach(field => {
      if (data[field] !== undefined) {
        data[field] = null;
      }
    });

    // Clear computed fields
    data.mean = 0;
    data.rubric = '';
  }

  return data;
};

// Helper to normalize query parameters for consistent filtering
const normalizeClassName = (className) => {
  if (!className) return '';
  return className.trim().toLowerCase().replace(/\s+/g, ' ').replace(/[^\w\s]/g, '').trim();
};

const normalizeExamType = (examType) => {
  if (!examType) return '';
  return examType.trim().toLowerCase().replace(/\s+/g, ' ').replace(/[^\w\s]/g, '').trim();
};

// Get all results (academicYear query parameter optional for backward compatibility)
router.get('/', async (req, res) => {
  try {
    const { academicYear } = req.query;

    // Validate academic year (use default if not provided for backward compatibility)
    const validation = validateAcademicYear(academicYear, true);
    if (!validation.isValid) {
      return res.status(400).json({ error: validation.message });
    }

    const results = await Result.find({ 
      academicYearKey: validation.academicYear 
    });
    res.json(results);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Get results by exam type (academicYear query parameter optional for backward compatibility)
router.get('/exam/:examType', async (req, res) => {
  try {
    const { academicYear } = req.query;
    const { examType } = req.params;

    // Validate academic year (use default if not provided for backward compatibility)
    const validation = validateAcademicYear(academicYear, true);
    if (!validation.isValid) {
      return res.status(400).json({ error: validation.message });
    }

    const results = await Result.find({ 
      examTypeKey: normalizeExamType(examType),
      academicYearKey: validation.academicYear
    });
    res.json(results);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Get results by class (academicYear query parameter optional for backward compatibility)
router.get('/class/:className', async (req, res) => {
  try {
    const { academicYear } = req.query;
    const { className } = req.params;

    // Validate academic year (use default if not provided for backward compatibility)
    const validation = validateAcademicYear(academicYear, true);
    if (!validation.isValid) {
      return res.status(400).json({ error: validation.message });
    }

    const results = await Result.find({ 
      classKey: normalizeClassName(className),
      academicYearKey: validation.academicYear
    });
    res.json(results);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Get results by class and exam type (academicYear query parameter optional for backward compatibility)
router.get('/class/:className/exam/:examType', async (req, res) => {
  try {
    const { academicYear } = req.query;
    const { className, examType } = req.params;

    // Validate academic year (use default if not provided for backward compatibility)
    const validation = validateAcademicYear(academicYear, true);
    if (!validation.isValid) {
      return res.status(400).json({ error: validation.message });
    }

    const results = await Result.find({ 
      classKey: normalizeClassName(className),
      examTypeKey: normalizeExamType(examType),
      academicYearKey: validation.academicYear
    });
    res.json(results);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Add a new result (academicYear required)
router.post('/', async (req, res) => {
  try {
    const resultData = { ...req.body };

    // Validate required fields
    if (!resultData.name || !resultData.class || !resultData.examType) {
      return res.status(400).json({ 
        error: 'Name, class, and examType are required fields' 
      });
    }

    // Validate academic year
    const academicValidation = validateAcademicYear(resultData.academicYear);
    if (!academicValidation.isValid) {
      return res.status(400).json({ error: academicValidation.message });
    }

    // Validate exam status
    const statusValidation = validateExamStatus(resultData.examStatus);
    if (!statusValidation.isValid) {
      return res.status(400).json({ error: statusValidation.message });
    }

    // Ensure academicYear and examStatus are set
    resultData.academicYear = academicValidation.academicYear;
    resultData.examStatus = statusValidation.examStatus;

    // Process exam status (clear scores for absent students)
    processExamStatusData(resultData);

    const result = new Result(resultData);
    const savedResult = await result.save();
    res.status(201).json(savedResult);
  } catch (err) {
    // Handle unique constraint violations
    if (err.code === 11000) {
      return res.status(409).json({ 
        error: 'A record for this student, class, exam type, term, and academic year already exists' 
      });
    }
    res.status(400).json({ error: err.message });
  }
});

// Update a result (academicYear required if provided)
router.put('/:id', async (req, res) => {
  try {
    const updateData = { ...req.body };

    // Validate academic year if it's being updated
    if (updateData.academicYear) {
      const academicValidation = validateAcademicYear(updateData.academicYear);
      if (!academicValidation.isValid) {
        return res.status(400).json({ error: academicValidation.message });
      }
      updateData.academicYear = academicValidation.academicYear;
    }

    // Validate exam status if it's being updated
    if (updateData.examStatus !== undefined) {
      const statusValidation = validateExamStatus(updateData.examStatus);
      if (!statusValidation.isValid) {
        return res.status(400).json({ error: statusValidation.message });
      }
      updateData.examStatus = statusValidation.examStatus;
    }

    // Process exam status (clear scores for absent students)
    processExamStatusData(updateData);

    const result = await Result.findByIdAndUpdate(
      req.params.id,
      updateData,
      { new: true }
    );

    if (!result) {
      return res.status(404).json({ error: 'Result not found' });
    }

    res.json(result);
  } catch (err) {
    // Handle unique constraint violations
    if (err.code === 11000) {
      return res.status(409).json({ 
        error: 'A record for this student, class, exam type, term, and academic year already exists' 
      });
    }
    res.status(400).json({ error: err.message });
  }
});

// Delete a result
router.delete('/:id', async (req, res) => {
  try {
    await Result.findByIdAndDelete(req.params.id);
    res.json({ success: true });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

module.exports = router;

