import React, { useState } from 'react';
import { useLocation } from 'react-router-dom';
import DataEntryGrid from '../Components/DataEntryGrid';
import { calculateMean, calculateRubric } from '../Utils/calculations';
import { addResult, updateResult, fetchResultsByClassAndType } from '../api/results';
import ExamNavigation from '../Components/ExamNavigation';
import { getSubjectsByClass } from '../Utils/subjectsByClass';

const EndtermExam = () => {
  const location = useLocation();
  // Get selectedClass from route state (preferred for dashboard integration)
  const selectedClass =
    location.state?.selectedClass ||
    new URLSearchParams(location.search).get('class') ||
    'Playgroup';
  const selectedTerm = location.state?.selectedTerm || 'Term 1';
  const selectedYear = location.state?.selectedYear || '2025';

  const subjects = getSubjectsByClass(selectedClass);

  const createInitialStudent = () => {
    const student = { id: Date.now() + Math.random(), name: '', mean: '', rubric: '', examType: 'endterm', class: selectedClass, term: selectedTerm, academicYear: selectedYear };
    subjects.forEach(subject => {
      student[subject] = '';
    });
    return student;
  };

  const [students, setStudents] = useState([createInitialStudent()]);

  const saveStudent = async (student) => {
    const studentWithClassAndTerm = { ...student, class: selectedClass, term: selectedTerm, academicYear: selectedYear };

    if (student._id) {
      // If student already has an _id, update the existing record
      await updateResult(student._id, studentWithClassAndTerm);
    } else {
      // Check if student already exists for this exam type
      try {
        const existingResults = await fetchResultsByClassAndType(selectedClass, 'endterm', selectedYear);
        const existingStudent = existingResults.find(result => 
          result.name.trim().toLowerCase() === student.name.trim().toLowerCase() &&
          result.term === selectedTerm
        );

        if (existingStudent) {
          // Update existing record
          await updateResult(existingStudent._id, studentWithClassAndTerm);
        } else {
          // Create new record
          await addResult(studentWithClassAndTerm);
        }
      } catch (error) {
        console.error('Error checking for existing student:', error);
        // Fallback to creating new record if check fails
        await addResult(studentWithClassAndTerm);
      }
    }
  };

  const updateStudent = (id, field, value) => {
    setStudents(prevStudents => {
      return prevStudents.map(student => {
        if (student.id === id) {
          const newStudent = { ...student, [field]: value, examType: 'endterm', class: selectedClass, term: selectedTerm, academicYear: selectedYear };

          // Handle exam status changes
          const examStatus = newStudent.examStatus || 'sat';

          if (examStatus === 'absent') {
            // For absent students: clear ALL scores unconditionally, set mean to 0, no rubric
            subjects.forEach(subject => {
              newStudent[subject] = ''; // Clear all subjects consistently
            });
            newStudent.mean = 0;
            newStudent.rubric = '';
          } else if (examStatus === 'incomplete') {
            // For incomplete students: allow partial calculation, no rubric if incomplete
            const subjectScores = subjects.map(subject => parseFloat(newStudent[subject])).filter(score => !isNaN(score));
            if (subjectScores.length > 0) {
              newStudent.mean = calculateMean(subjectScores);
              newStudent.rubric = ''; // No rubric for incomplete
            } else {
              newStudent.mean = 0;
              newStudent.rubric = '';
            }
          } else {
            // For students who sat the exam: calculate normally
            const subjectScores = subjects.map(subject => parseFloat(newStudent[subject])).filter(score => !isNaN(score));

            if (subjectScores.length === subjects.length) {
              newStudent.mean = calculateMean(subjectScores);
              newStudent.rubric = calculateRubric(newStudent.mean);
            } else {
              newStudent.mean = '';
              newStudent.rubric = '';
            }
          }

          // Mark as modified for auto-save
          newStudent._modified = Date.now();
          return newStudent;
        }
        return student;
      });
    });
  };

  const addStudentRow = (preConfiguredStudent = null) => {
    // Check if there's already an empty row to prevent duplicates
    const hasEmptyRow = students.some(s => 
      (!s.name || s.name.trim() === '') && 
      subjects.every(subject => !s[subject] || s[subject] === '')
    );

    // Don't add if we already have an empty row (unless it's a pre-configured student)
    if (!preConfiguredStudent && hasEmptyRow) {
      return;
    }

    const newStudent = preConfiguredStudent || {
      id: Date.now() + Math.random(),
      name: '',
      mean: '',
      rubric: '',
      examType: 'endterm',
      class: selectedClass || '',
      term: selectedTerm || 'Term 1',
      academicYear: selectedYear || '2025'
    };

    if (!preConfiguredStudent) {
      subjects.forEach(subject => {
        newStudent[subject] = '';
      });
    }

    setStudents([...students, newStudent]);
  };

  const styles = {
    container: {
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      minHeight: '100vh',
      padding: '20px',
      fontFamily: '"Inter", "Segoe UI", Tahoma, Geneva, Verdana, sans-serif'
    },
    contentWrapper: {
      maxWidth: '1600px',
      margin: '0 auto',
      background: 'rgba(255, 255, 255, 0.95)',
      borderRadius: '24px',
      padding: '40px',
      boxShadow: '0 20px 60px rgba(0, 0, 0, 0.1)',
      backdropFilter: 'blur(10px)'
    },
    header: {
      display: 'flex',
      alignItems: 'center',
      gap: '20px',
      marginBottom: '40px',
      padding: '20px',
      background: 'linear-gradient(135deg, #f8fafc 0%, #e2e8f0 100%)',
      borderRadius: '16px',
      boxShadow: '0 4px 20px rgba(0, 0, 0, 0.05)'
    },
    logo: {
      height: '60px',
      width: 'auto',
      borderRadius: '12px',
      boxShadow: '0 4px 16px rgba(0, 0, 0, 0.1)'
    },
    title: {
      fontSize: '2.5rem',
      fontWeight: '700',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      WebkitBackgroundClip: 'text',
      WebkitTextFillColor: 'transparent',
      margin: 0,
      letterSpacing: '-1px'
    },
    subtitle: {
      fontSize: '1.1rem',
      color: '#6b7280',
      fontWeight: '500',
      marginTop: '8px'
    }
  };

  return (
    <div style={styles.container}>
      <ExamNavigation />
      <div style={styles.contentWrapper}>
        <div style={styles.header}>
          <img 
            src="/logschool.png" 
            alt="School Logo" 
            style={styles.logo}
          />
          <div>
            <h1 style={styles.title}>Endterm Exam Results</h1>
            <p style={styles.subtitle}>{selectedYear} - {selectedTerm} - Class: {selectedClass} | Enter and manage student scores</p>
          </div>
        </div>
        <DataEntryGrid
          students={students}
          updateStudent={updateStudent}
          addStudentRow={addStudentRow}
          saveStudent={saveStudent}
          selectedClass={selectedClass}
          selectedYear={selectedYear}
        />
      </div>
    </div>
  );
};

export default EndtermExam;

