                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Subject Averages Section */}
      {classStats && (
        <div style={{
          marginTop: '15px',
          padding: '15px',
          background: 'linear-gradient(135deg, #f8fafc 0%, #e2e8f0 100%)',
