const API_URL = window.location.hostname === 'localhost'
  ? 'http://localhost:5000/api/results'
  : `${window.location.protocol}//${window.location.hostname}:5000/api/results`;

export const fetchResults = async (academicYear = null) => {
  const url = academicYear ? `${API_URL}?academicYear=${academicYear}` : API_URL;
  return (await fetch(url)).json();
};

export const fetchResultsByType = async (type, academicYear = null) => {
  const url = academicYear ? `${API_URL}/exam/${type}?academicYear=${academicYear}` : `${API_URL}/exam/${type}`;
  return (await fetch(url)).json();
};

export const fetchResultsByClass = async (className, academicYear = null) => {
  const url = academicYear ? `${API_URL}/class/${className}?academicYear=${academicYear}` : `${API_URL}/class/${className}`;
  return (await fetch(url)).json();
};

export const fetchResultsByClassAndType = async (className, examType, academicYear = null) => {
  const url = academicYear ? `${API_URL}/class/${className}/exam/${examType}?academicYear=${academicYear}` : `${API_URL}/class/${className}/exam/${examType}`;
  return (await fetch(url)).json();
};

export const addResult = async (data) => {
  const response = await fetch(API_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data)
  });

  if (!response.ok) {
    throw new Error(`Failed to add result: ${response.statusText}`);
  }

  return response.json();
};

export const updateResult = async (id, data) =>
  (await fetch(`${API_URL}/${id}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data)
  })).json();

export const deleteResult = async (id) =>
  (await fetch(`${API_URL}/${id}`, { method: 'DELETE' })).json();

