import React, { useState, useEffect, useCallback, useRef } from 'react';
import { getSubjectsByClass, getSubjectDisplayName } from '../Utils/subjectsByClass';
import { fetchResults } from '../api/results';

const DataEntryGrid = ({ students, updateStudent, addStudentRow, saveStudent, selectedClass, selectedExamType, selectedTerm, selectedYear }) => {
  const subjects = getSubjectsByClass(selectedClass || 'Grade 1');
  const [existingStudents, setExistingStudents] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [savingStudents, setSavingStudents] = useState(new Set());
  const [savedStudents, setSavedStudents] = useState(new Set());

  // Auto-save function with debouncing
  const autoSaveStudent = useCallback(async (student) => {
    // Check if all required fields are filled
    const hasName = student.name && student.name.trim() !== '';
    const examStatus = student.examStatus || 'sat';

    // For absent students, only name and exam status are required
    // For others, all subjects must be filled
    const isReadyToSave = hasName && (
      examStatus === 'absent' || 
      examStatus === 'incomplete' ||
      subjects.every(subject => 
        student[subject] && student[subject] !== '' && !isNaN(parseFloat(student[subject]))
      )
    );

    if (isReadyToSave && !savingStudents.has(student.id)) {
      // Use callback to get current state to avoid stale closure
      setSavingStudents(prev => {
        if (prev.has(student.id)) return prev; // Already saving
        return new Set(prev).add(student.id);
      });

      try {
        await saveStudent(student);
        setSavedStudents(prev => new Set(prev).add(student.id));

        // Add new student name to existing students list if not already present
        if (!existingStudents.includes(student.name)) {
          setExistingStudents(prev => [...prev, student.name].sort());
        }

        // Add new empty row after successful save (handled separately)
        // This ensures continuous data entry workflow
        if (addStudentRow) {
          setTimeout(() => {
            // Check current state to avoid duplicate empty rows
            addStudentRow(); // Add new empty row below completed entry
          }, 500); // Small delay to ensure save completion
        }

        // Remove from saving set after a delay to show success state
        setTimeout(() => {
          setSavingStudents(prev => {
            const newSet = new Set(prev);
            newSet.delete(student.id);
            return newSet;
          });
        }, 1000);

      } catch (error) {
        console.error('Auto-save failed:', error);
        setSavingStudents(prev => {
          const newSet = new Set(prev);
          newSet.delete(student.id);
          return newSet;
        });
      }
    }
  }, [subjects, saveStudent, existingStudents]); // eslint-disable-line react-hooks/exhaustive-deps

  // Use ref to track timeouts per student ID to prevent multiple saves
  const studentTimeouts = useRef(new Map());

  // Debounced auto-save effect
  useEffect(() => {
    students.forEach(student => {
      if (student.name && student.name.trim() !== '') {
        // Clear existing timeout for this student
        if (studentTimeouts.current.has(student.id)) {
          clearTimeout(studentTimeouts.current.get(student.id));
        }

        // Set new timeout for this student
        const timeout = setTimeout(() => {
          autoSaveStudent(student);
          studentTimeouts.current.delete(student.id);
        }, 1500); // 1.5 second delay

        studentTimeouts.current.set(student.id, timeout);
      }
    });

    // Cleanup function to clear all timeouts when component unmounts
    return () => {
      studentTimeouts.current.forEach(timeout => clearTimeout(timeout));
      studentTimeouts.current.clear();
    };
  }, [students, autoSaveStudent]);

  // Fetch existing students for the selected class
  useEffect(() => {
    const fetchExistingStudents = async () => {
      if (!selectedClass) return;

      setIsLoading(true);
      try {
        const allResults = await fetchResults(selectedYear);
        // Get unique student names for the selected class
        const classStudents = allResults
          .filter(result => result.class === selectedClass)
          .map(result => result.name)
          .filter((name, index, array) => array.indexOf(name) === index) // Remove duplicates
          .filter(name => name && name.trim() !== '') // Remove empty names
          .sort(); // Sort alphabetically

        setExistingStudents(classStudents);
      } catch (error) {
        console.error('Error fetching existing students:', error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchExistingStudents();
  }, [selectedClass, selectedYear]);

  // Auto-populate students when class changes or when no students exist
  useEffect(() => {
    if (existingStudents.length > 0 && students.length === 0) {
      // Create student objects with existing names
      existingStudents.forEach((studentName, index) => {
        const newStudent = {
          id: Date.now() + index,
          name: studentName,
          class: selectedClass,
          examType: selectedExamType,
          term: selectedTerm,
          academicYear: selectedYear
        };

        // Initialize all subjects to empty
        subjects.forEach(subject => {
          newStudent[subject] = '';
        });

        // Add the student to the grid
        setTimeout(() => addStudentRow(newStudent), index * 10); // Small delay to prevent ID conflicts
      });
    }
  }, [existingStudents, students.length, selectedClass, selectedExamType, selectedTerm, selectedYear, subjects, addStudentRow]);

  const styles = {
    container: {
      fontFamily: 'Arial, sans-serif',
      padding: '20px',
      backgroundColor: '#f8f9fa',
      borderRadius: '12px',
      boxShadow: '0 4px 20px rgba(0,0,0,0.1)'
    },
    tableWrapper: {
      overflowX: 'auto',
      maxHeight: '600px',
      border: '1px solid #e9ecef',
      borderRadius: '8px',
      backgroundColor: '#fff'
    },
    table: {
      width: '100%',
      borderCollapse: 'collapse',
      fontSize: '13px',
      minWidth: '800px'
    },
    tableHeader: {
      backgroundColor: '#4a90e2',
      color: '#fff',
      fontWeight: 'bold',
      padding: '15px 8px',
      textAlign: 'center',
      fontSize: '12px',
      borderBottom: '2px solid #357abd',
      position: 'sticky',
      top: '0',
      zIndex: '10'
    },
    tableCell: {
      padding: '8px',
      borderBottom: '1px solid #e9ecef',
      textAlign: 'center'
    },
    input: {
      width: '100%',
      padding: '8px',
      border: '1px solid #ddd',
      borderRadius: '4px',
      fontSize: '12px',
      textAlign: 'center',
      backgroundColor: '#fff',
      transition: 'border-color 0.2s ease',
      boxSizing: 'border-box'
    },
    nameInput: {
      textAlign: 'left',
      minWidth: '120px'
    },
    statusIndicator: {
      padding: '6px 12px',
      borderRadius: '20px',
      fontSize: '11px',
      fontWeight: 'bold',
      textAlign: 'center',
      minWidth: '80px',
      display: 'inline-block'
    },
    statusSaving: {
      backgroundColor: '#fff3cd',
      color: '#856404',
      border: '1px solid #ffeaa7'
    },
    statusSaved: {
      backgroundColor: '#d1edff',
      color: '#0c5460',
      border: '1px solid #bee5eb'
    },
    statusPending: {
      backgroundColor: '#f8f9fa',
      color: '#6c757d',
      border: '1px solid #dee2e6'
    },
    addButton: {
      padding: '12px 24px',
      backgroundColor: '#007bff',
      color: '#fff',
      border: 'none',
      borderRadius: '6px',
      cursor: 'pointer',
      fontSize: '14px',
      fontWeight: 'bold',
      marginTop: '20px',
      transition: 'background-color 0.2s ease'
    },
    tableRowEven: {
      backgroundColor: '#f8f9fa'
    },
    tableRowOdd: {
      backgroundColor: '#fff'
    }
  };

  return (
    <div style={styles.container}>
      <div style={{ marginBottom: '20px' }}>
        <h3 style={{ color: '#2c3e50', fontSize: '18px', margin: 0 }}>
          Enter the marks - {selectedClass || 'Grade 1'}
          {isLoading && <span style={{ color: '#007bff', marginLeft: '10px' }}>Loading students...</span>}
          {existingStudents.length > 0 && !isLoading && (
            <span style={{ color: '#28a745', marginLeft: '10px', fontSize: '14px' }}>
              ({existingStudents.length} students found)
            </span>
          )}
        </h3>
        <p style={{ color: '#6c757d', fontSize: '14px', margin: '8px 0 0 0' }}>
          💡 Data saves automatically when required fields are completed (Name + subjects for Sat students, Name only for Absent/Incomplete)
        </p>
      </div>

      <div style={styles.tableWrapper}>
        <table style={styles.table}>
          <thead>
            <tr>
              <th style={{...styles.tableHeader, minWidth: '120px'}}>Name</th>
              <th style={{...styles.tableHeader, minWidth: '100px'}}>Exam Status</th>
              {subjects.map(subject => (
                <th key={subject} style={{...styles.tableHeader, minWidth: '80px'}}>
                  {getSubjectDisplayName(subject)}
                </th>
              ))}
              <th style={{...styles.tableHeader, minWidth: '80px'}}>Mean</th>
              <th style={{...styles.tableHeader, minWidth: '80px'}}>Rubric</th>
              <th style={{...styles.tableHeader, minWidth: '80px'}}>Class</th>
              <th style={{...styles.tableHeader, minWidth: '90px'}}>Status</th>
            </tr>
          </thead>
          <tbody>
            {students.map((student, index) => (
              <tr 
                key={student.id || student._id || index}
                style={index % 2 === 0 ? styles.tableRowEven : styles.tableRowOdd}
              >
                <td style={styles.tableCell}>
                  <div style={{ position: 'relative' }}>
                    <input
                      style={{...styles.input, ...styles.nameInput}}
                      type="text"
                      value={student.name || ''}
                      onChange={e => {
                        const value = e.target.value;
                        if (/^[a-zA-Z\s'-]*$/.test(value)) {
                          updateStudent(student.id, 'name', value);

                          // If this is a new name and it's complete, add it to the existing students list
                          if (value.trim() !== '' && 
                              !existingStudents.includes(value.trim()) && 
                              value.trim().split(' ').length >= 2) { // Assume full name has at least 2 words
                            setExistingStudents(prev => [...prev, value.trim()].sort());
                          }
                        }
                      }}
                      placeholder="Student name or select from list"
                      onFocus={(e) => e.target.style.borderColor = '#4a90e2'}
                      onBlur={(e) => e.target.style.borderColor = '#ddd'}
                      list={`studentNames-${student.id}`}
                    />
                    <datalist id={`studentNames-${student.id}`}>
                      {existingStudents.map(name => (
                        <option key={name} value={name} />
                      ))}
                    </datalist>
                  </div>
                </td>
                <td style={styles.tableCell}>
                  <select
                    style={{
                      ...styles.input,
                      cursor: 'pointer',
                      backgroundColor: student.examStatus === 'absent' ? '#ffe6e6' : 
                                     student.examStatus === 'incomplete' ? '#fff3cd' : '#e8f5e9'
                    }}
                    value={student.examStatus || 'sat'}
                    onChange={e => {
                      const newStatus = e.target.value;
                      updateStudent(student.id, 'examStatus', newStatus);

                      // If setting to absent, clear all subject scores
                      if (newStatus === 'absent') {
                        subjects.forEach(subject => {
                          updateStudent(student.id, subject, '');
                        });
                      }
                    }}
                    onFocus={(e) => e.target.style.borderColor = '#4a90e2'}
                    onBlur={(e) => e.target.style.borderColor = '#ddd'}
                  >
                    <option value="sat">Sat</option>
                    <option value="absent">Absent</option>
                    <option value="incomplete">Incomplete</option>
                  </select>
                </td>
                {subjects.map(subject => (
                  <td key={subject} style={styles.tableCell}>
                    <input
                      style={{
                        ...styles.input,
                        backgroundColor: student.examStatus === 'absent' ? '#f8f9fa' : '#fff',
                        color: student.examStatus === 'absent' ? '#6c757d' : 'inherit'
                      }}
                      type="number"
                      min="0"
                      max="100"
                      value={student[subject] || ''}
                      disabled={student.examStatus === 'absent'}
                      onChange={e => {
                        if (student.examStatus === 'absent') return; // Prevent changes for absent students

                        const value = e.target.value;
                        if (value === '') {
                          updateStudent(student.id, subject, '');
                          return;
                        }
                        const numValue = parseFloat(value);
                        if (!isNaN(numValue) && numValue >= 0 && numValue <= 100) {
                          updateStudent(student.id, subject, value);
                        }
                      }}
                      placeholder={student.examStatus === 'absent' ? 'ABS' : '0-100'}
                      onFocus={(e) => {
                        if (student.examStatus !== 'absent') {
                          e.target.style.borderColor = '#4a90e2';
                        }
                      }}
                      onBlur={(e) => {
                        if (student.examStatus !== 'absent') {
                          e.target.style.borderColor = '#ddd';
                        }
                      }}
                    />
                  </td>
                ))}
                <td style={styles.tableCell}>
                  <strong style={{ color: '#2980b9' }}>
                    {typeof student.mean === 'number' ? student.mean.toFixed(2) : '-'}
                  </strong>
                </td>
                <td style={styles.tableCell}>
                  <strong style={{ color: '#27ae60' }}>
                    {student.rubric || '-'}
                  </strong>
                </td>
                <td style={styles.tableCell}>
                  <strong>{student.class || selectedClass || '-'}</strong>
                </td>
                <td style={styles.tableCell}>
                  {(() => {
                    const hasName = student.name && student.name.trim() !== '';
                    const examStatus = student.examStatus || 'sat';
                    const hasAllSubjects = subjects.every(subject => 
                      student[subject] && student[subject] !== '' && !isNaN(parseFloat(student[subject]))
                    );

                    // Determine if the student is ready based on exam status
                    const isReady = hasName && (
                      examStatus === 'absent' || 
                      examStatus === 'incomplete' ||
                      hasAllSubjects
                    );

                    if (savingStudents.has(student.id)) {
                      return (
                        <span style={{...styles.statusIndicator, ...styles.statusSaving}}>
                          💾 Saving...
                        </span>
                      );
                    } else if (savedStudents.has(student.id) && isReady) {
                      return (
                        <span style={{...styles.statusIndicator, ...styles.statusSaved}}>
                          ✅ Saved
                        </span>
                      );
                    } else if (isReady) {
                      return (
                        <span style={{...styles.statusIndicator, ...styles.statusSaved}}>
                          ✅ Complete
                        </span>
                      );
                    } else {
                      const missingFields = [];
                      if (!hasName) missingFields.push('Name');

                      // Only check for missing subjects if status is 'sat'
                      if (examStatus === 'sat') {
                        const missingSubjects = subjects.filter(subject => 
                          !student[subject] || student[subject] === '' || isNaN(parseFloat(student[subject]))
                        );
                        missingFields.push(...missingSubjects);
                      }

                      return (
                        <span 
                          style={{...styles.statusIndicator, ...styles.statusPending}}
                          title={`Missing: ${missingFields.length > 0 ? missingFields.join(', ') : 'Required fields for ' + examStatus}`}
                        >
                          ⏳ Pending
                        </span>
                      );
                    }
                  })()}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div style={{ display: 'flex', gap: '10px', marginTop: '20px', flexWrap: 'wrap' }}>
        <button 
          style={styles.addButton}
          onClick={addStudentRow}
          onMouseEnter={(e) => e.target.style.backgroundColor = '#0056b3'}
          onMouseLeave={(e) => e.target.style.backgroundColor = '#007bff'}
        >
          + Add Student
        </button>

        {existingStudents.length > 0 && students.length === 0 && (
          <button 
            style={{
              ...styles.addButton,
              backgroundColor: '#28a745',
              ':hover': { backgroundColor: '#218838' }
            }}
            onClick={() => {
              existingStudents.forEach((studentName, index) => {
                const newStudent = {
                  id: Date.now() + index,
                  name: studentName,
                  class: selectedClass,
                  examType: selectedExamType,
                  term: selectedTerm
                };

                subjects.forEach(subject => {
                  newStudent[subject] = '';
                });

                setTimeout(() => addStudentRow(newStudent), index * 10);
              });
            }}
            onMouseEnter={(e) => e.target.style.backgroundColor = '#218838'}
            onMouseLeave={(e) => e.target.style.backgroundColor = '#28a745'}
          >
            📋 Load All {existingStudents.length} Students
          </button>
        )}
      </div>
    </div>
  );
};

export default DataEntryGrid;

