import React, { useEffect, useState } from 'react';
import {
  fetchResults,
  addResult,
  updateResult,
  deleteResult
} from '../api/results';
import ExamNavigation from '../Components/ExamNavigation';
import { getSubjectsByClass, getSubjectDisplayName, getRubric } from '../Utils/subjectsByClass';

const examTypes = ['opener', 'midterm', 'endterm'];
const terms = ['Term 1', 'Term 2', 'Term 3'];
const classes = [
  'Playgroup', 'PP1', 'PP2', 'Grade 1', 'Grade 2', 'Grade 3',
  'Grade 4', 'Grade 5', 'Grade 6', 'Grade 7', 'Grade 8', 'Grade 9'
];

const showFeedback = (message, setFeedback) => {
  setFeedback(message);
  setTimeout(() => setFeedback(''), 3000);
};

const createEmptyResult = (examType, selectedClass, selectedTerm) => {
  const subjects = getSubjectsByClass(selectedClass);
  const result = {
    name: '',
    mean: '',
    rubric: '',
    examType: examType,
    class: selectedClass || '',
    term: selectedTerm || 'Term 1'
  };

  // Initialize all subjects to empty string
  subjects.forEach(subject => {
    result[subject] = '';
  });

  return result;
};

const ResultsManager = () => {
  const [results, setResults] = useState([]);
  const [form, setForm] = useState({});
  const [editingId, setEditingId] = useState(null);
  const [selectedExamType, setSelectedExamType] = useState('opener');
  const [selectedClass, setSelectedClass] = useState('');
  const [selectedTerm, setSelectedTerm] = useState('Term 1');
  const [searchQuery, setSearchQuery] = useState('');
  const [feedback, setFeedback] = useState('');

  useEffect(() => {
    fetchResults().then(setResults);
  }, []);

  useEffect(() => {
    // Reset form when class, exam type, or term changes
    setForm(createEmptyResult(selectedExamType, selectedClass, selectedTerm));
    setEditingId(null);
  }, [selectedClass, selectedExamType, selectedTerm]);

  const currentSubjects = getSubjectsByClass(selectedClass);

  const handleChange = e => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleEdit = result => {
    setEditingId(result._id);
    setSelectedExamType(result.examType);
    setSelectedClass(result.class);
    setSelectedTerm(result.term || 'Term 1');

    const editForm = {
      name: result.name,
      mean: result.mean,
      rubric: result.rubric,
      examType: result.examType,
      class: result.class || '',
      term: result.term || 'Term 1'
    };

    // Get subjects for the result's class
    const resultSubjects = getSubjectsByClass(result.class);

    // Add all subjects for this class
    resultSubjects.forEach(subject => {
      editForm[subject] = result[subject] || '';
    });

    setForm(editForm);
  };

  const handleDelete = async id => {
    if (window.confirm('Are you sure you want to delete this result?')) {
      await deleteResult(id);
      setResults(results.filter(r => r._id !== id));
      showFeedback('Result deleted successfully!', setFeedback);
    }
  };

  const handleSearch = () => {
    if (searchQuery.trim()) {
      const foundStudents = results.filter(r => 
        r.name.toLowerCase().includes(searchQuery.toLowerCase()) &&
        r.examType === selectedExamType &&
        (!selectedClass || r.class === selectedClass) &&
        r.term === selectedTerm
      );

      if (foundStudents.length > 0) {
        showFeedback(`Found ${foundStudents.length} student${foundStudents.length > 1 ? 's' : ''}`, setFeedback);
      } else {
        showFeedback('No students found matching your search', setFeedback);
      }
    }
  };

  const handleSubmit = async e => {
    e.preventDefault();

    if (!form.class) {
      alert('Please select a class.');
      return;
    }

    // Calculate mean from current subjects
    const subjectScores = currentSubjects.map(subject => parseFloat(form[subject])).filter(score => !isNaN(score));
    const mean = subjectScores.length > 0 ? subjectScores.reduce((a, b) => a + b, 0) / subjectScores.length : 0;

    const formWithMean = { 
      ...form, 
      mean: mean.toFixed(2),
      rubric: getRubric(mean),
      term: selectedTerm
    };

    if (editingId) {
      const updated = await updateResult(editingId, formWithMean);
      setResults(results.map(r => (r._id === editingId ? updated : r)));
      setEditingId(null);
      showFeedback('Result updated successfully!', setFeedback);
    } else {
      const created = await addResult(formWithMean);
      setResults([...results, created]);
      showFeedback('Result saved successfully!', setFeedback);
    }
    setForm(createEmptyResult(selectedExamType, selectedClass, selectedTerm));
  };

  // Filter results by selected exam type, class, term, and search query
  const filteredResults = results.filter(r => {
    const matchesExamType = r.examType === selectedExamType;
    const matchesClass = !selectedClass || r.class === selectedClass;
    const matchesTerm = r.term === selectedTerm;
    const matchesSearch = !searchQuery || r.name.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesExamType && matchesClass && matchesTerm && matchesSearch;
  });

  const styles = {
    container: {
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      minHeight: '100vh',
      padding: '20px',
      fontFamily: '"Inter", "Segoe UI", Tahoma, Geneva, Verdana, sans-serif'
    },
    contentWrapper: {
      maxWidth: '1400px',
      margin: '0 auto',
      background: 'rgba(255, 255, 255, 0.95)',
      borderRadius: '24px',
      padding: '40px',
      boxShadow: '0 20px 60px rgba(0, 0, 0, 0.1)',
      backdropFilter: 'blur(10px)'
    },
    header: {
      textAlign: 'center',
      marginBottom: '40px'
    },
    title: {
      fontSize: '3rem',
      fontWeight: '700',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      WebkitBackgroundClip: 'text',
      WebkitTextFillColor: 'transparent',
      marginBottom: '10px',
      letterSpacing: '-1px'
    },
    subtitle: {
      fontSize: '1.2rem',
      color: '#6b7280',
      fontWeight: '400'
    },
    filtersContainer: {
      background: 'linear-gradient(135deg, #f8fafc 0%, #e2e8f0 100%)',
      borderRadius: '16px',
      padding: '24px',
      marginBottom: '32px',
      display: 'flex',
      gap: '24px',
      alignItems: 'center',
      flexWrap: 'wrap',
      boxShadow: '0 4px 20px rgba(0, 0, 0, 0.05)'
    },
    filterGroup: {
      display: 'flex',
      flexDirection: 'column',
      gap: '8px'
    },
    label: {
      fontSize: '0.9rem',
      fontWeight: '600',
      color: '#374151',
      letterSpacing: '0.5px'
    },
    select: {
      padding: '12px 16px',
      borderRadius: '12px',
      border: '2px solid #e5e7eb',
      fontSize: '1rem',
      color: '#374151',
      fontWeight: '500',
      background: '#fff',
      cursor: 'pointer',
      transition: 'all 0.3s ease',
      outline: 'none',
      minWidth: '160px'
    },
    formContainer: {
      background: 'linear-gradient(135deg, #fef3c7 0%, #fde68a 100%)',
      borderRadius: '16px',
      padding: '24px',
      marginBottom: '32px',
      boxShadow: '0 4px 20px rgba(0, 0, 0, 0.05)'
    },
    formTitle: {
      fontSize: '1.5rem',
      fontWeight: '700',
      color: '#92400e',
      marginBottom: '20px',
      textAlign: 'center'
    },
    form: {
      display: 'grid',
