      color: '#6b7280'
    },
    emptyIcon: {
      fontSize: '4rem',
      marginBottom: '16px',
      opacity: '0.5'
    },
    emptyText: {
      fontSize: '1.2rem',
      fontWeight: '500'
    }
  };

  return (
    <div style={styles.container}>
      <ExamNavigation />
      <div style={styles.contentWrapper}>
        <div style={styles.header}>
          <h1 style={styles.title}>Results Manager</h1>
          <p style={styles.subtitle}>Manage and organize student examination results</p>
        </div>

        {feedback && (
          <div style={{
            padding: '12px 20px',
            background: 'linear-gradient(135deg, #10b981 0%, #059669 100%)',
            color: '#fff',
            borderRadius: '12px',
            marginBottom: '20px',
            textAlign: 'center',
            fontWeight: '600',
            boxShadow: '0 4px 16px rgba(16, 185, 129, 0.3)'
          }}>
            {feedback}
          </div>
        )}

        <div style={styles.filtersContainer}>
          <div style={styles.filterGroup}>
            <label style={styles.label}>Term</label>
            <select
              value={selectedTerm}
              onChange={e => setSelectedTerm(e.target.value)}
              style={styles.select}
            >
              {terms.map(term => (
                <option key={term} value={term}>{term}</option>
              ))}
            </select>
          </div>

          <div style={styles.filterGroup}>
            <label style={styles.label}>Exam Type</label>
            <select
              value={selectedExamType}
              onChange={e => setSelectedExamType(e.target.value)}
              style={styles.select}
            >
              {examTypes.map(type => (
                <option key={type} value={type}>
                  {type.charAt(0).toUpperCase() + type.slice(1)}
                </option>
              ))}
            </select>
          </div>

          <div style={styles.filterGroup}>
            <label style={styles.label}>Class Filter</label>
            <select
              value={selectedClass}
              onChange={e => setSelectedClass(e.target.value)}
              style={styles.select}
            >
              <option value="">All Classes</option>
              {classes.map(cls => (
                <option key={cls} value={cls}>{cls}</option>
              ))}
            </select>
          </div>

          <div style={styles.filterGroup}>
            <label style={styles.label}>Search Student</label>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
              <input
                type="text"
                placeholder="Search by name..."
                value={searchQuery}
                onChange={e => setSearchQuery(e.target.value)}
                onKeyPress={e => {
                  if (e.key === 'Enter') {
                    handleSearch();
                  }
                }}
                style={{
                  ...styles.select,
                  minWidth: '200px'
                }}
              />
              <button
                onClick={handleSearch}
                style={{
                  padding: '12px 16px',
                  borderRadius: '12px',
                  border: 'none',
                  background: 'linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%)',
                  color: '#fff',
                  cursor: 'pointer',
                  fontSize: '1rem',
                  fontWeight: '600',
                  transition: 'all 0.3s ease',
                  boxShadow: '0 4px 16px rgba(99, 102, 241, 0.3)',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '4px'
                }}
                onMouseEnter={(e) => {
                  e.target.style.transform = 'scale(1.05)';
                  e.target.style.boxShadow = '0 6px 20px rgba(99, 102, 241, 0.4)';
                }}
                onMouseLeave={(e) => {
                  e.target.style.transform = 'scale(1)';
                  e.target.style.boxShadow = '0 4px 16px rgba(99, 102, 241, 0.3)';
                }}
              >
                🔍
              </button>
            </div>
          </div>

          <div style={{ marginLeft: 'auto', textAlign: 'right' }}>
            <div style={{ fontSize: '0.9rem', color: '#6b7280', marginBottom: '4px' }}>Total Results</div>
            <div style={{ fontSize: '2rem', fontWeight: '700', color: '#1f2937' }}>
              {filteredResults.length}
            </div>
          </div>
        </div>

        <div style={styles.formContainer}>
          <h3 style={styles.formTitle}>
            {editingId ? '✏️ Edit Student Result' : '➕ Add New Student Result'}
          </h3>
          <form onSubmit={handleSubmit} style={styles.form}>
            <input 
              name="name" 
              value={form.name || ''} 
              onChange={handleChange} 
              placeholder="Student Name" 
              required 
              style={{
                ...styles.input,
                ':focus': { borderColor: '#10b981', boxShadow: '0 0 0 3px rgba(16, 185, 129, 0.1)' }
              }}
            />

            {currentSubjects.map(subject => (
              <input 
                key={subject}
                name={subject} 
                type="number" 
                value={form[subject] || ''} 
                onChange={handleChange} 
                placeholder={getSubjectDisplayName(subject)} 
                required 
                style={styles.input}
                min="0"
                max="100"
              />
            ))}

            <select
              name="class"
              value={form.class || ''}
              onChange={handleChange}
              required
              style={styles.select}
            >
              <option value="">Select Class</option>
              {classes.map(cls => (
                <option key={cls} value={cls}>{cls}</option>
              ))}
            </select>

            <select
              name="term"
              value={form.term || selectedTerm}
              onChange={handleChange}
              required
              style={styles.select}
            >
              {terms.map(term => (
                <option key={term} value={term}>{term}</option>
              ))}
            </select>

            <button 
              type="submit" 
              style={{
                ...styles.buttonPrimary,
                ':hover': { transform: 'translateY(-2px)', boxShadow: '0 6px 20px rgba(16, 185, 129, 0.4)' }
              }}
            >
              {editingId ? '💾 Update' : '➕ Add'} Result
            </button>

            {editingId && (
              <button 
                type="button" 
                onClick={() => { 
                  setEditingId(null); 
                  setForm(createEmptyResult(selectedExamType, selectedClass, selectedTerm)); 
                }}
                style={styles.buttonSecondary}
              >
                ❌ Cancel
              </button>
            )}
          </form>
        </div>

        <div style={styles.tableContainer}>
          {filteredResults.length > 0 ? (
            <div style={styles.tableWrapper}>
              <table style={styles.table}>
                <thead style={styles.tableHeader}>
                <tr>
                  <th style={styles.th}>👤 Student Name</th>
                  {currentSubjects.map(subject => (
                    <th key={subject} style={styles.th}>📚 {getSubjectDisplayName(subject)}</th>
                  ))}
                  <th style={styles.th}>📊 Mean</th>
                  <th style={styles.th}>📋 Rubric</th>
                  <th style={styles.th}>🏫 Class</th>
                  <th style={styles.th}>📅 Term</th>
                  <th style={{ ...styles.th, minWidth: '180px' }}>⚙️ Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredResults.map((r, index) => (
                  <tr 
                    key={r._id} 
                    style={{
                      ...styles.row,
                      backgroundColor: index % 2 === 0 ? '#f8fafc' : '#fff',
                      ':hover': { backgroundColor: '#e0f2fe', transform: 'scale(1.01)' }
                    }}
                  >
                    <td style={{ ...styles.td, fontWeight: '600', color: '#1f2937' }}>{r.name}</td>
                    {currentSubjects.map(subject => (
                      <td key={subject} style={styles.td}>
                        {r[subject] ? (
                          <span style={{ 
                            padding: '4px 8px', 
                            borderRadius: '6px', 
                            background: r[subject] >= 80 ? '#dcfce7' : r[subject] >= 65 ? '#fef3c7' : r[subject] >= 50 ? '#fed7aa' : '#fecaca',
                            color: r[subject] >= 80 ? '#166534' : r[subject] >= 65 ? '#92400e' : r[subject] >= 50 ? '#9a3412' : '#991b1b',
                            fontWeight: '600'
                          }}>
                            {r[subject]}
                          </span>
                        ) : '-'}
                      </td>
                    ))}
                    <td style={styles.td}>
                      <span style={{ 
                        padding: '6px 12px', 
                        borderRadius: '8px', 
                        background: 'linear-gradient(135deg, #3b82f6 0%, #2563eb 100%)',
                        color: '#fff',
                        fontWeight: '700',
                        fontSize: '0.9rem'
                      }}>
                        {r.mean || '-'}
                      </span>
                    </td>
                    <td style={styles.td}>
                      <span style={{ 
                        padding: '4px 8px', 
                        borderRadius: '6px', 
                        background: '#f3f4f6',
                        color: '#374151',
                        fontWeight: '600',
                        fontSize: '0.85rem'
                      }}>
                        {r.rubric || '-'}
                      </span>
                    </td>
                    <td style={styles.td}>{r.class}</td>
                    <td style={styles.td}>{r.term || 'Term 1'}</td>
                    <td style={{ ...styles.td, minWidth: '180px', whiteSpace: 'nowrap' }}>
                      <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                        <button 
                          onClick={() => handleEdit(r)} 
                          style={{ ...styles.actionButton, ...styles.editButton }}
                          title="Edit Result"
                          onMouseEnter={(e) => {
                            e.target.style.transform = 'scale(1.05)';
                            e.target.style.boxShadow = '0 4px 12px rgba(59, 130, 246, 0.4)';
                          }}
                          onMouseLeave={(e) => {
                            e.target.style.transform = 'scale(1)';
                            e.target.style.boxShadow = '0 2px 8px rgba(59, 130, 246, 0.3)';
                          }}
                        >
                          ✏️ Edit
                        </button>
                        <button 
                          onClick={() => handleDelete(r._id)} 
                          style={{ ...styles.actionButton, ...styles.deleteButton }}
                          title="Delete Result - This action cannot be undone"
                          onMouseEnter={(e) => {
                            e.target.style.transform = 'scale(1.05)';
                            e.target.style.boxShadow = '0 4px 12px rgba(239, 68, 68, 0.4)';
                          }}
                          onMouseLeave={(e) => {
                            e.target.style.transform = 'scale(1)';
                            e.target.style.boxShadow = '0 2px 8px rgba(239, 68, 68, 0.3)';
                          }}
                        >
                          🗑️ Delete
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            </div>
          ) : (
            <div style={styles.emptyState}>
              <div style={styles.emptyIcon}>📊</div>
              <div style={styles.emptyText}>No results found for the selected filters</div>
              <p style={{ marginTop: '8px', color: '#9ca3af' }}>
                Select a class and add some student results to get started
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ResultsManager;

